## Construtor Padrão

Usando `function` (antes do ES6):

```js
function Pessoa(nome) {
  this.nome = nome;
}

Pessoa.prototype.falar = function() {
  console.log(`Oi, meu nome é ${this.nome}`);
};

const p = new Pessoa("Murilo");
p.falar(); // Oi, meu nome é Murilo
```

Com `class` (ES6), que já usa prototype por baixo:

```js
class Pessoa {
  constructor(nome) {
    this.nome = nome;
  }

  falar() {
    console.log(`Oi, meu nome é ${this.nome}`);
  }
}
```

Isso é **equivalente** a fazer:

```js
Pessoa.prototype.falar = function() {
  console.log(`Oi, meu nome é ${this.nome}`);
};
```

## Resumo

Antes do ES6, usavámos o prototype como orientação a objeto. Exemplo:

```js
// "Classe" Person como objeto literal
var Person = {
    init: function(nome, sobrenome) {
        this.nome = nome;
        this.sobrenome = sobrenome;
    },

    nome_completo: function() {
        return this.nome + " " + this.sobrenome;
    }
};

// Criando uma instância usando Object.create
var murilo = Object.create(Person);
murilo.init("Murilo", "Freitas");

console.log(murilo.nome_completo()); // Murilo Freitas
```

Ou, podemos passar os atributos diretamente no método `create`:

```json
var Person = {
    nome_completo: function () {
        return this.nome + " " + this.sobrenome;
    }
};

var murilo = Object.create(Person, {
    nome: { value: "Murilo" },
    sobrenome: { value: "Freitas" }
});

console.log(murilo.nome_completo()); // Murilo Freitas
```


Ou, podemos usar uma função construtora:

```js
function PersonFactory(nome, sobrenome) {
    this.nome = nome;
    this.sobrenome = sobrenome;

    this.nomeCompleto = function() {
        return this.nome + " " + this.sobrenome;
    };
}
```

# Classes

De maneira mais moderna, usamos classes:

```js
class Person {
    constructor(nome, sobrenome) {
        this.nome = nome;
        this.sobrenome = sobrenome;
    }

    nomeCompleto() {
        return this.nome + " " + this.sobrenome;
    }
}

const murilo = new Person("Murilo", "Freitas");
console.log(murilo.nomeCompleto()); // Murilo Freitas

```

